// DEA reverse distributor directory. Every registrant on the copies of DEA Diversion Control's "Registered Reverse
// Distributors" list we could find (hosted by state boards and university EHS offices), and which copies each one is on.
// GENERATED by scratchpad gen_rd.py from the research dataset: re-run it rather than hand-editing rows. Public sources only:
// no DEA registration numbers or street addresses. Easy Rx Cycle is listed under its legal name like everyone else.

export type RdKind = "reverse-distributor" | "environmental" | "medical-waste" | "institution" | "other";

export type RdCompany = {
  name: string;
  formerNames?: string[];
  website?: string;
  hq: string; // "City, ST" as printed on the DEA list
  states: string[]; // states of the listed registrations (latest list where present)
  kind: RdKind;
  onLatest: boolean; // on the October 2025 DEA list
  collector: boolean; // noted as an authorized collector on the October 2025 list
  lists: string[]; // YYYY-MM of each DEA list copy it appears on, newest first
};

export const RD_KIND_LABEL: Record<RdKind, string> = {
  "reverse-distributor": "Pharmaceutical reverse distributor",
  environmental: "Environmental / hazardous waste",
  "medical-waste": "Medical waste",
  institution: "In-house (university, manufacturer, government)",
  other: "Other / unclear",
};

